THOUGHT: The durable core is now in place and compiles. Next I’ll add the HTTP server with the essential auth, workspace, channel, message, reaction, search, profile, file, invitation, group, read-state, and health routes, plus a minimal WebSocket implementation that can subscribe and replay channel events.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os,sys,json,re,urllib.parse,threading,time,base64,hashlib,socket,struct,html,cgi
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
import core
NODE=int(os.environ.get('NODE_ID','0')); PORT=int(os.environ.get('PORT','8000'))
WS_CLIENTS=[]; WS_LOCK=threading.RLock()
def sendws(s,obj):
    b=json.dumps(obj,separators=(',',':')).encode(); n=len(b)
    if n<126: h=bytes([0x81,n])
    elif n<65536:h=bytes([0x81,126])+struct.pack('>H',n)
    else:h=bytes([0x81,127])+struct.pack('>Q',n)
    try:s.sendall(h+b); return True
def broadcast(cid,event):
    with WS_LOCK:
        for x in list(WS_CLIENTS):
            if x['cid']==cid: sendws(x['s'],event)
def event_poller():
    last={}
    while True:
        try:
            c=core.db()
            rows=c.execute('SELECT * FROM events ORDER BY channel_id,event_id').fetchall()
            for r in rows:
                if r['event_id']>last.get(r['channel_id'],0):
                    p=json.loads(r['payload_json']); p.update(type=r['type'],event_id=r['event_id'],channel_id=r['channel_id']); broadcast(r['channel_id'],p); last[r['channel_id']]=r['event_id']
            c.close()
        except: pass
        time.sleep(.05)
threading.Thread(target=event_poller,daemon=True).start()
def html_page():
 return '''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>
*{box-sizing:border-box}body{margin:0;font:14px Arial;color:#222}.app{display:flex;height:100vh}.side{width:260px;background:#3f0f42;color:white;padding:18px}.main{flex:1;padding:24px}.thread{width:330px;border-left:1px solid #ddd;padding:18px}.modal{position:fixed;inset:0;background:#0008;display:flex;align-items:center;justify-content:center}.modal>form{background:#fff;padding:25px;border-radius:8px;min-width:320px}button{border:0;padding:9px 14px;border-radius:4px;color:#fff;cursor:pointer}.primary{background:#007a5a}.danger{background:#e01e5a}.secondary{background:#1264a3}input,textarea{padding:9px;margin:5px 0;width:100%}.hidden{display:none}.msg{padding:12px;border-bottom:1px solid #eee}.toolbar{display:none}.msg:hover .toolbar{display:block}.reaction-picker{display:grid;grid-template-columns:repeat(4,1fr)}
</style></head><body><div id=auth-modal class=modal><form data-testid=auth-form data-mode=login><h2>Huddle</h2><div data-testid=auth-error></div><input name=username placeholder=username><input name=password type=password placeholder=password><input name=display_name placeholder=display_name><button type=submit data-testid=auth-submit data-button-role=primary>Log in</button><button type=button data-testid=auth-toggle class=secondary>Sign up</button></form></div>
<div class=app><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=current-user></div><button data-testid=new-channel-btn data-button-role=secondary>New channel</button><h3>Channels</h3><div data-testid=channel-list></div><div data-testid=dms-list></div><button data-testid=logout-btn data-button-role=danger>Logout</button></aside><main class=main><h2 data-testid=channel-title></h2><div data-testid=channel-topic></div><div data-testid=message-list></div><form id=message-form><input data-testid=message-input placeholder="Message"><button class=primary data-testid=send-btn data-button-role=primary>Send</button></form></main><aside class="thread hidden" data-testid=thread-panel><button class=secondary data-testid=close-thread data-button-role=secondary>Close</button><div id=thread-content></div><form id=thread-form><input data-testid=thread-input><button class=primary data-testid=thread-send data-button-role=primary>Reply</button></form></aside></div>
<div id=create-channel-modal class="modal hidden"><form data-testid=create-channel-form><input name=name><label><input type=checkbox name=is_private data-testid=create-channel-private> private</label><div data-testid=create-channel-error></div><button class=primary data-testid=create-channel-submit data-button-role=primary>Create</button><button type=button class=secondary data-testid=create-channel-cancel data-button-role=secondary>Cancel</button></form></div>
<div id=workspace-settings-modal class="modal hidden"></div><div id=channel-settings-modal class="modal hidden"></div>
<script>
const $=s=>document.querySelector(s), token=()=>localStorage.getItem('huddle.token'); let me,ws,ch,thread;
async function api(path,opt={}){opt.headers={...(opt.headers||{}),Authorization:'Bearer '+token(),'Content-Type':'application/json'};let r=await fetch('/api'+path,opt);let d=await r.json().catch(()=>({}));if(!r.ok)throw d;return d}
function auth(){let f=$('[data-testid=auth-form]');f.onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(f));try{let d=await fetch('/api/auth/'+(f.dataset.mode==='register'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});let j=await d.json();if(!d.ok)throw j;localStorage.setItem('huddle.token',j.token);location.reload()}catch(e){$('[data-testid=auth-error]').textContent=e.error||'Invalid input'}}; $('[data-testid=auth-toggle]').onclick=()=>{f.dataset.mode=f.dataset.mode==='login'?'register':'login';f.querySelector('[data-testid=auth-submit]').textContent=f.dataset.mode==='login'?'Log in':'Sign up'}}
async function load(){try{let x=await api('/auth/me');me=x.user;$('#auth-modal').classList.add('hidden');$('[data-testid=current-user]').textContent=me.username;let q=await api('/workspaces');if(!q.workspaces.length){$('.main').innerHTML+='<div data-testid=empty-state-create-workspace>No workspace yet</div>';return}ws=q.workspaces[0];$('[data-testid=workspace-header]').textContent=ws.name;let z=await api('/workspaces/'+ws.slug);renderChannels(z.channels);select(z.channels[0])}catch(e){$('#auth-modal').classList.remove('hidden')}}
function renderChannels(a){$('[data-testid=channel-list]').innerHTML=a.map(x=>`<div data-testid=channel-entry data-channel-id="${x.id}" data-channel-name="${x.name}" onclick='selectBy(${x.id})'># ${x.name}</div>`).join('')}
async function selectBy(id){let z=await api('/workspaces/'+ws.slug);select(z.channels.find(x=>x.id==id))}
async function select(x){if(!x)return;ch=x;$('[data-testid=channel-title]').textContent=x.name;$('[data-testid=channel-topic]').textContent=x.topic||'';renderMessages((await api('/channels/'+x.id+'/messages')).messages)}
function renderMessages(a){let box=$('[data-testid=message-list]');box.innerHTML=a.filter(x=>!x.parent_id).map(m=>`<div class=msg data-testid=message data-message-id="${m.id}"><b data-testid=message-author>${m.author.display_name}</b> <span data-testid=message-time>${new Date(m.created_at).toLocaleTimeString()}</span><div data-testid=message-body>${esc(m.body)}</div>${m.edited_at?'<span data-testid=edited-indicator>(edited)</span>':''}<span data-testid=reply-count>${m.reply_count?m.reply_count+' repl'+(m.reply_count==1?'y':'ies'):''}</span><div class=toolbar><button data-testid=open-thread-btn onclick='openThread(${m.id})'>Thread</button><button data-testid=reaction-button onclick='react(${m.id})'>☺</button>${m.author_id==me.id?`<button data-testid=edit-message-btn onclick='editMsg(${m.id})'>Edit</button><button data-testid=delete-message-btn onclick='delMsg(${m.id})'>Delete</button>`:''}</div>${m.reactions.map(r=>`<button class=reaction-chip data-testid=reaction-chip onclick='unreact(${m.id},${JSON.stringify(r.emoji)})'>${r.emoji} ${r.count}</button>`).join('')}</div>`).join('')||'<div data-testid=empty-channel>No messages yet — say hi!</div>'}
function esc(s){return (s||'').replace(/[&<>"]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[x]))}
async function refresh(){if(ch)renderMessages((await api('/channels/'+ch.id+'/messages')).messages)}
async function post(body,parent){await api('/channels/'+ch.id+'/messages',{method:'POST',body:JSON.stringify({body,parent_id:parent||null})});refresh()}
$('#message-form').onsubmit=e=>{e.preventDefault();let i=$('[data-testid=message-input]');if(i.value.trim()){post(i.value);i.value=''}}
function openThread(id){thread=id;$('.thread').classList.remove('hidden');$('#thread-content').textContent='Thread';}
$('#thread-form').onsubmit=e=>{e.preventDefault();let i=$('[data-testid=thread-input]');if(i.value.trim()){post(i.value,thread);i.value=''}}
$('[data-testid=close-thread]').onclick=()=>$('.thread').classList.add('hidden');
async function react(id){let e=prompt('emoji','👍');if(e)await api('/messages/'+id+'/reactions',{method:'POST',body:JSON.stringify({emoji:e})}),refresh()}
async function unreact(id,e){await api('/messages/'+id+'/reactions/'+encodeURIComponent(e),{method:'DELETE'});refresh()}
async function editMsg(id){let v=prompt('Edit');if(v)await api('/messages/'+id,{method:'PATCH',body:JSON.stringify({body:v})}),refresh()}
async function delMsg(id){await api('/messages/'+id,{method:'DELETE'});refresh()}
$('[data-testid=logout-btn]').onclick=()=>{localStorage.removeItem('huddle.token');location.reload()};auth();load();
</script></body></html>'''
def jsonbody(h):
 try:
  n=int(h.headers.get('Content-Length','0')); x=json.loads(h.rfile.read(n) or '{}'); return x if isinstance(x,dict) else None
 except:return None
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def log_message(self,*a): pass
 def out(self,code,obj,headers=None):
  b=json.dumps(obj,separators=(',',':')).encode();self.send_response(code);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.send_header('Connection','close')
  for k,v in (headers or {}).items():self.send_header(k,v)
  self.end_headers();self.wfile.write(b)
 def user(self):
  a=self.headers.get('Authorization',''); return core.token_user(a[7:] if a.startswith('Bearer ') else '')
 def do_GET(self):
  p=urllib.parse.urlparse(self.path); path=p.path; q=urllib.parse.parse_qs(p.query)
  if path=='/': b=html_page().encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
  if path=='/api/health':return self.out(200,{'status':'ok','node_id':NODE})
  if path=='/api/ws': return self.websocket(q.get('token',[''])[0])
  u=self.user()
  if path=='/api/auth/me':
   return self.out(200,{'user':core.user_obj(u)}) if u else self.out(401,{'error':'unauthorized'})
  if not u:return self.out(401,{'error':'unauthorized'})
  c=core.db()
