```mswea_bash_command
cat > /app/irc.py <<'PY'
import socketserver, threading, socket, core
NICKS=set(); LOCK=threading.RLock()
def send(c,line):
    try:c.sendall((line+'\r\n').encode())
    except OSError:pass
class S(socketserver.StreamRequestHandler):
    def handle(self):
        self.nick=None; self.user=None; self.token=None; self.registered=False; self.authed=False
        while True:
            try:
                raw=self.rfile.readline()
                if not raw:break
                line=raw.decode('utf-8','replace').rstrip('\r\n')
                if not line:continue
                a=line.split(' ',1); cmd=a[0].upper(); rest=a[1] if len(a)>1 else ''
                if cmd=='PASS':
                    self.token=rest.strip(); self.authed=bool(core.token_user(self.token))
                    if not self.authed:send(self.request,':huddle 464 * :Password incorrect'); return
                elif cmd=='NICK':
                    n=rest.split()[0] if rest.split() else ''
                    with LOCK:
                        if n in NICKS and n!=self.nick:
                            send(self.request,f':huddle 433 * {n} :Nickname is already in use');continue
                        if self.nick:NICKS.discard(self.nick)
                        self.nick=n;NICKS.add(n)
                    self.maybe_register()
                elif cmd=='USER':
                    self.user=rest;self.maybe_register()
                elif cmd=='PING':
                    x=rest[1:] if rest.startswith(':') else rest;send(self.request,f':huddle PONG huddle :{x}')
                elif cmd=='PONG':pass
                elif cmd=='QUIT':return
                elif cmd in ('MODE','WHO','LIST','NAMES','TOPIC'):pass
                elif self.registered:
                    send(self.request,f':huddle 421 {self.nick} {cmd} :Unknown command')
            except (ConnectionError,OSError):break
    def maybe_register(self):
        if self.registered or not self.nick or not self.user:return
        if not self.authed:
            send(self.request,':huddle 464 * :Password incorrect');return
        self.registered=True; n=self.nick
        for code,text in [('001',f'Welcome to Huddle, {n}'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle 1.0 o o'),('005','CHANTYPES=# :are supported by this server')]:
            send(self.request,f':huddle {code} {n} :{text}')
        send(self.request,f':huddle 422 {n} :MOTD File is missing')
    def finish(self):
        if self.nick:
            with LOCK:NICKS.discard(self.nick)
        super().finish()
class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address=True
if __name__=='__main__':
    with Server(('0.0.0.0',6667),S) as srv:srv.serve_forever()
